    Orders are served in order: priority ascending, then order_day ascending,
    then order_id ascending. Stock given to one order is unavailable to later
    orders. Returns a dict order_id -> {sku: allocated eaches} with an entry for
    every order and every SKU on its lines (0 where nothing was allocated).
    Inputs are not modified.

    Raises ValueError on a duplicate order_id or a line qty <= 0.
    """
    seen = set()
    for order_id, _priority, _order_day, lines in orders:
        if order_id in seen:
            raise ValueError("duplicate order_id: %s" % order_id)
        seen.add(order_id)
        for sku, qty in lines.items():
            if qty <= 0:
                raise ValueError("line qty must be > 0 for order %s sku %s" % (order_id, sku))

    stock = {sku: int(qty) for sku, qty in available.items()}

    ordered = sorted(orders, key=lambda o: (o[1], o[2], o[0]))

    result: Dict[str, Dict[str, int]] = {}
    for order_id, _priority, _order_day, lines in ordered:
        alloc: Dict[str, int] = {sku: 0 for sku in lines}
        # All-or-nothing: only allocate if every line can be fully satisfied.
        can_ship = all(stock.get(sku, 0) >= qty for sku, qty in lines.items())
        if can_ship:
            for sku, qty in lines.items():
                stock[sku] = stock.get(sku, 0) - qty
                alloc[sku] = qty
        result[order_id] = alloc

    return result"}}}

